from lib import *
S = SS('j244')
steps = [
    step("回滚等于旧版本代码重新面对新版本的表结构。在真实 PostgreSQL 16.15 上,v1 的 3 条语句(INSERT name+age、SELECT id,name,age、UPDATE age = age + 1)在 8 种迁移之后:M1 新增可空列、M4 新增带默认值的 NOT NULL 列、M8 int 改 bigint:3 条都成功;M2 给有 2 行的表新增无默认值的 NOT NULL 列,迁移本身就失败(contains null values);M3 在空表上新增 NOT NULL 列:v1 的 INSERT 失败(violates not-null constraint);M5 列改名 name → full_name:INSERT 与 SELECT 失败(column \"name\" does not exist);M6 删除 age:3 条全失败;M7 age 改成 text:UPDATE 失败(operator does not exist: text + integer)。", t=tl(S(1)), done=lidx(S(1), 'M1 新增可空列', 'M4 新增 NOT NULL 列并带默认值', 'M8 age 从 int 改成 bigint'), mark=lidx(S(1), 'M2 新增 NOT NULL 列(表里有 2 行', 'M3 新增 NOT NULL 列(空表', 'M5 列改名', 'M6 删除列 age', 'M7 age 改成 text'), b=bars([['M1', 3, '3/3'], ['M3', 2, '2/3'], ['M4', 3, '3/3'], ['M5', 1, '1/3'], ['M6', 0, '0/3'], ['M7', 2, '2/3'], ['M8', 3, '3/3']], 3, done=[0, 1, 2, 3, 4, 5, 6]), kv=KV([['对旧代码安全', '新增可空列 / 带默认值的列 / int→bigint'], ['让旧代码失败', 'NOT NULL 无默认值、改名、删列、改类型']], ['让旧代码失败'])),
    step("回滚迁移不等于回到原状。把 status 文本换成 status_code(1 = active、2 = inactive、其它 = 0)并删除 status 列,再用 down 迁移加回 status:表结构与迁移前相同,但数据校验和不一致——原来 c 是 pending、d 是 banned,现在都成了 unknown(5 行里 2 行变了)。另一个例子:v2 上线后给新增的 email 列写入了 3 行,回滚(DROP COLUMN email)再重新升级(ADD COLUMN email)之后有 email 的行是 0。", t=tl(S(2)), done=lidx(S(2), 'up:status', '写入了 3 行 email'), mark=lidx(S(2), 'down 之后表结构与迁移前相同', '有 email 的行:0'), kv=KV([['有损的 up(其它 → 0)', 'down 后 pending / banned 变成 unknown'], ['DROP COLUMN 回滚再升级', '3 行 email → 0 行']], ['有损的 up(其它 → 0)'])),
    step("Java 序列化的回滚:没有显式 serialVersionUID 时,v2(新增字段 coupon)写的文件 v1 读不了,v1 写的文件 v2 也读不了,都是 InvalidClassException: local class incompatible(两边的 serialVersionUID 是由类结构算出的,互不相同)。固定 serialVersionUID = 1 后 v1 能读 v2 写的文件(coupon 被丢弃),v2 能读 v1 写的文件(coupon = null)。往返:v2 写入 coupon = VIP-99,v2 自己读得到;回滚到 v1 读出再原样写回,再升级回 v2 读:coupon = null——v1 的类里没有这个字段,回滚期间的读写把它静默丢掉了。", t=tl(S(3)), done=lidx(S(3), '没有 serialVersionUID', 'InvalidClassException', '固定 serialVersionUID = 1'), mark=lidx(S(3), '往返:v2 写入 coupon = VIP-99', '回滚到 v1,v1 读出再写回'), kv=KV([['无固定 UID', '两个方向都抛 InvalidClassException'], ['固定 UID = 1', '都能读,v1 丢掉 coupon'], ['v2 → v1 读写 → v2', 'coupon: VIP-99 → null']], ['v2 → v1 读写 → v2'])),
    step("滚动发布时 v1 和 v2 同时在线:共 200 行(v1 写 100 行 name,v2 写 100 行)。v2 只写新列 full_name:v1 读 name 时有 100 行是 NULL,v2 读 full_name 时有 100 行是 NULL;v2 双写 name 与 full_name:v1 读 name 看到 NULL 的行是 0,v2 读 full_name 看到 NULL 的行仍是 100(那是 v1 写的行)。回填 UPDATE ... SET full_name = name 之后两种情况 v2 看到 NULL 的行都是 0。扩展阶段必须双写,并且要回填旧行。", t=tl(S(4)), done=lidx(S(4), 'v2 只写新列 full_name'), mark=lidx(S(4), 'v2 双写 name 与 full_name'), b=bars([['只写新列:v1 看到 NULL', 100, '100'], ['双写:v1 看到 NULL', 0, '0'], ['回填前:v2 看到 NULL', 100, '100'], ['回填后:v2 看到 NULL', 0, '0']], 100, done=[0, 1, 2, 3]), kv=KV([['v2 只写新列', 'v1 看到 100 行 NULL'], ['v2 双写', 'v1 看到 0 行 NULL'], ['回填后', 'v2 看到 0 行 NULL']], ['v2 双写'])),
]
A = mkartj('j244', 244, 'Java,发布,回滚,数据库迁移,序列化,滚动发布,真实验证,动画演示',
    '在真实 PostgreSQL 16.15 与 Java 序列化上实测回滚:8 种迁移里改名、删列、NOT NULL 无默认值会让 v1 的语句失败;down 迁移让 pending / banned 变成 unknown,DROP COLUMN 后再升级丢掉 3 行 email;序列化的字段在 v1 往返后被静默丢弃;滚动窗口只写新列时 v1 看到 100 行 NULL。',
    '回滚测试要确认的不是“能不能再部署旧版本”,而是旧版本能不能正确读写新版本留下的数据。这篇用真实数据库和 Java 序列化量出:哪些迁移旧代码扛得住,回滚迁移丢什么,以及滚动窗口里两个版本同时写会发生什么。',
    [('8 种迁移', '其中改名、删列、NOT NULL 无默认值、改类型会让 v1 的语句失败,新增可空列与 int→bigint 不会'), ('VIP-99 → null', '回滚到 v1 读出再写回,再升级回 v2 时 coupon 字段的值'), ('100 / 200', 'v2 只写新列时 v1 读 name 看到 NULL 的行数(双写时 0)')],
    [('旧代码 vs 新表结构', None), ('回滚迁移的数据损失', None), ('序列化往返', None), ('滚动发布窗口', None)],
    steps, [ENV_J + '。真实数据库是本机 Homebrew 的 PostgreSQL 16.15(独立数据目录、端口 9501);v1 的“代码”是 3 条 SQL(用 psql 执行),序列化部分是 JDK 21.0.12 的两个版本的 Order 类', '没有验证:Flyway / Liquibase 的 undo 与 baseline、Kubernetes 的滚动更新与回滚命令、金丝雀与蓝绿发布、消息队列里的消息格式、真实的 v1 / v2 应用进程(这里的“应用”是 SQL 与最小的 Java 类)、PostgreSQL 之外的数据库对 DDL 的锁与回滚行为'], '发布回滚测试')
